namespace Frisket
{
    /// <summary>
    /// Reed-Solomon over GF(256), which is what lets a QR code survive being torn,
    /// smudged or partly covered. Only the encoding half is here: the engine writes
    /// codes and never reads one.
    /// </summary>
    internal static class ReedSolomon
    {
        private static readonly byte[] Exp = new byte[512];
        private static readonly byte[] Log = new byte[256];

        static ReedSolomon()
        {
            // The field QR uses, generated by x^8 + x^4 + x^3 + x^2 + 1.
            int x = 1;
            for (int i = 0; i < 255; i++)
            {
                Exp[i] = (byte)x;
                Log[x] = (byte)i;
                x <<= 1;
                if (x >= 256)
                    x ^= 0x11D;
            }

            for (int i = 255; i < 512; i++)
                Exp[i] = Exp[i - 255];
        }

        private static byte Multiply(byte a, byte b)
            => a == 0 || b == 0 ? (byte)0 : Exp[Log[a] + Log[b]];

        /// <summary>
        /// The generator polynomial for <paramref name="degree"/> check symbols, as
        /// (x - a^0)(x - a^1)... expanded. Returned highest power first and monic, so
        /// index 0 is the leading 1 that division never needs.
        ///
        /// Built lowest-first because that is the order the multiplication reads in, then
        /// reversed once: mixing the two conventions is the mistake this invites, and it
        /// produces a code that looks right and scans as nothing.
        /// </summary>
        internal static byte[] Generator(int degree)
        {
            var low = new byte[degree + 1];
            low[0] = 1;

            for (int i = 0; i < degree; i++)
            {
                byte root = Exp[i];
                for (int k = i + 1; k >= 1; k--)
                    low[k] = (byte)(low[k - 1] ^ Multiply(root, low[k]));
                low[0] = Multiply(root, low[0]);
            }

            var high = new byte[degree + 1];
            for (int i = 0; i <= degree; i++)
                high[i] = low[degree - i];

            return high;
        }

        /// <summary>The check symbols for a block of data.</summary>
        public static byte[] Remainder(byte[] data, int degree)
        {
            byte[] generator = Generator(degree);
            var remainder = new byte[degree];

            foreach (byte b in data)
            {
                byte factor = (byte)(b ^ remainder[0]);
                Array.Copy(remainder, 1, remainder, 0, degree - 1);
                remainder[degree - 1] = 0;

                for (int i = 0; i < degree; i++)
                    remainder[i] ^= Multiply(generator[i + 1], factor);
            }

            return remainder;
        }
    }
}
